/* LÈLE ESSENTIALS — STORE CONFIGURATION
   To set your actual selling prices, replace price: null with a number in BDT.
   To add a new product, add an object below, supply its image, and create a detail page.
   This static GitHub Pages site uses WhatsApp for customer-submitted COD orders.
*/
const STORE = Object.freeze({name:'Lèle Essentials Co.', whatsapp:'8801729228117', phone2:'8801970155970', currency:'BDT'});
const PRODUCTS = [
 {id:'sakura-set', slug:'sakura-set', name:'Japan Sakura Skincare Ritual Set', label:'THE COMPLETE RITUAL', brand:'LAIKOU', category:'Skincare Sets', size:'5-piece collection', image:'sakura-set.webp', price:null, badge:'The full ritual', tone:'rose', short:'Five beautifully coordinated essentials for a thoughtful daily skincare routine.', intro:'A considered five-step ritual in delicate sakura-pink packaging. The collection pairs a cleanser, toner, serum, eye cream and essence cream for a complete everyday routine.', includes:[['Cleanser','50 g'],['Toner','100 ml'],['Serum','17 ml'],['Eye cream','15 g'],['Essence cream','25 g']], highlights:['A five-piece routine','Sakura-inspired collection','A beautiful giftable set'], directions:['Cleanse gently and rinse thoroughly.','Apply toner to clean skin.','Smooth on a few drops of serum.','Gently pat eye cream around the orbital area, avoiding direct contact with eyes.','Finish with essence cream. Use daytime sunscreen separately.'], notes:'Retailer listings identify these five items and sizes, and list the country of origin as China; “Japan Sakura” is the product name, not a manufacturing-origin claim. Ingredient references vary by listing; consult your physical packaging for the full ingredient list.'},
 {id:'sakura-mask', slug:'sakura-mask', name:'Japan Sakura Mud Mask', label:'THE SOFT RESET', brand:'LAIKOU', category:'Face Masks', size:'5 g / 0.18 oz sachet', image:'sakura-mask.webp', price:null, badge:'Gentle ritual', tone:'rose', short:'A single-use sakura-inspired mud mask for a moment of gentle facial care.', intro:'A soft pink sachet adorned with cherry blossoms and Mount Fuji artwork. The front label describes a hydrating, gentle-cleansing and oil-control mud mask.', includes:[['Format','Individual sachet'],['Net weight','5 g / 0.18 oz'],['Brand','LAIKOU']], highlights:['Hydrating — packaging claim','Gentle cleansing — packaging claim','Oil-control — packaging claim'], directions:['Check the back-of-pack directions before use.','Patch-test first and avoid broken or irritated skin.','Keep away from eyes and lips; rinse immediately if irritation occurs.','Follow the timing and rinsing instructions printed on your sachet.'], notes:'The front of the sachet does not show a full ingredient list or application time. We do not invent either; follow the product packaging.'},
 {id:'matcha-mask', slug:'matcha-mask', name:'Matcha Mud Mask', label:'THE GREEN RESET', brand:'LAIKOU', category:'Face Masks', size:'5 g / 0.18 oz sachet', image:'matcha-mask.webp', price:null, badge:'Matcha moment', tone:'sage', short:'A matcha-inspired mud mask sachet for a refreshing skincare pause.', intro:'Presented in fresh matcha green with a powdered-tea illustration. The front label promotes deep cleansing and hydration, alongside acne-related marketing claims.', includes:[['Format','Individual sachet'],['Net weight','5 g / 0.18 oz'],['Brand','LAIKOU']], highlights:['Deep cleansing — packaging claim','Hydrating — packaging claim','Acne-related claims appear on the packaging; results are not guaranteed'], directions:['Read the instructions and ingredients on the actual sachet before applying.','Patch-test first; do not use on irritated or broken skin.','Avoid contact with eyes and lips.','Follow the manufacturer’s application time and rinse instructions.'], notes:'The packaging makes acne-related claims; this cosmetic is not presented as a medical acne treatment. Full INCI ingredients are not visible in the supplied photograph.'}
];
const byId = Object.fromEntries(PRODUCTS.map(p=>[p.id,p]));
const asset = p => `${document.body.dataset.root || ''}assets/${p.image}`;
const detail = p => `${document.body.dataset.root || ''}products/${['sakura-set','sakura-mask','matcha-mask'].includes(p.slug) ? p.slug + '.html' : 'item.html?id=' + encodeURIComponent(p.id)}`;
const money = p => Number.isFinite(p.price) ? `৳${p.price.toLocaleString('en-BD')}` : 'Price on request';
const $ = (q, root=document) => root.querySelector(q);
const $$ = (q, root=document) => [...root.querySelectorAll(q)];
let cart = {};
try {const raw=JSON.parse(localStorage.getItem('lele_cart_v3')||'{}'); if(raw && typeof raw==='object') for(const [id,q] of Object.entries(raw)) if(byId[id]&&Number.isSafeInteger(q)&&q>0) cart[id]=Math.min(q,99);} catch {}
function save(){try{localStorage.setItem('lele_cart_v3',JSON.stringify(cart));}catch{} updateCart();}
function add(id,qty=1){if(!byId[id])return;cart[id]=Math.min(99,(cart[id]||0)+qty);save();openCart();announce(`${byId[id].name} added to bag`);}
function updateQty(id,diff){if(!byId[id])return;const n=(cart[id]||0)+diff;if(n<=0)delete cart[id];else cart[id]=Math.min(99,n);save();}
function announce(s){const el=$('#announce');if(el)el.textContent=s;}
function cartItems(){return Object.entries(cart).filter(([id,q])=>byId[id]&&q>0).map(([id,q])=>({...byId[id],qty:q}));}
function updateCart(){const items=cartItems(),total=items.reduce((s,p)=>s+p.qty,0);$$('[data-cart-count]').forEach(e=>e.textContent=total);const list=$('#cart-items');if(!list)return;list.innerHTML=items.length?items.map(p=>`<article class="bag-item"><img src="${asset(p)}" alt="${p.name}" width="96" height="100"><div><a class="bag-item-title" href="${detail(p)}">${p.name}</a><p>${p.size} · ${money(p)}</p><div class="qty-control"><button aria-label="Remove one ${p.name}" data-qty="-1" data-id="${p.id}">−</button><span>${p.qty}</span><button aria-label="Add one ${p.name}" data-qty="1" data-id="${p.id}">+</button></div></div><button class="remove-item" data-remove="${p.id}" aria-label="Remove ${p.name}">×</button></article>`).join(''):'<div class="empty-bag"><span class="empty-symbol">✿</span><h3>Your bag awaits.</h3><p>Thoughtful little luxuries are only a moment away.</p><button class="button button-dark" data-close-cart>Explore the collection</button></div>';
const summary=$('#bag-summary');if(summary){const allPriced=items.length&&items.every(p=>Number.isFinite(p.price));summary.textContent=allPriced?`Subtotal · ৳${items.reduce((s,p)=>s+p.price*p.qty,0).toLocaleString('en-BD')}`:'Product prices and delivery charges will be confirmed on WhatsApp.';}
const checkout=$('#checkout-open');if(checkout)checkout.disabled=!items.length;
}
function openCart(){const e=$('#cart-drawer'),b=$('#overlay');if(!e||!b)return;e.classList.add('is-open');e.setAttribute('aria-hidden','false');b.hidden=false;document.body.classList.add('locked');$('#cart-close')?.focus();}
function closeCart(){const e=$('#cart-drawer'),b=$('#overlay');e?.classList.remove('is-open');e?.setAttribute('aria-hidden','true');if(b)b.hidden=true;document.body.classList.remove('locked');}
function openCheckout(){if(!cartItems().length)return;closeCart();const modal=$('#checkout-modal');modal.hidden=false;document.body.classList.add('locked');$('#customer-name')?.focus();const summary=$('#checkout-products');if(summary)summary.innerHTML=cartItems().map(p=>`<div><span>${p.name} × ${p.qty}</span><strong>${money(p)}</strong></div>`).join('');}
function closeCheckout(){const modal=$('#checkout-modal');if(modal)modal.hidden=true;document.body.classList.remove('locked');}
function productCard(p){return `<article class="product-card"><a class="product-card-image ${p.tone}" href="${detail(p)}" aria-label="View ${p.name}"><span class="card-tag">${p.badge}</span><img src="${asset(p)}" alt="Product photograph of ${p.brand} ${p.name}" loading="lazy" width="700" height="700"><span class="card-view">Discover the ritual ↗</span></a><div class="product-card-info"><div class="eyebrow">${p.brand} · ${p.category}</div><a href="${detail(p)}" class="card-name">${p.name}</a><p>${p.short}</p><div class="product-card-bottom"><span>${money(p)}</span><button class="round-add" data-add="${p.id}" aria-label="Add ${p.name} to bag">+</button></div></div></article>`;}
function renderHome(){const g=$('#product-grid');if(!g)return;let active='All';const filters=$$('#filters button');const render=()=>{const term=($('#search-products')?.value||'').trim().toLowerCase();const items=PRODUCTS.filter(p=>(active==='All'||p.category===active)&&`${p.name} ${p.category} ${p.short}`.toLowerCase().includes(term));g.innerHTML=items.map(productCard).join('')||'<p class="no-results">No rituals match your search. Try another word.</p>';};filters.forEach(btn=>btn.addEventListener('click',()=>{active=btn.dataset.filter;filters.forEach(x=>{x.classList.toggle('active',x===btn);x.setAttribute('aria-pressed',String(x===btn));});render();}));$('#search-products')?.addEventListener('input',render);render();}
function renderProduct(){const id=document.body.dataset.product || new URLSearchParams(location.search).get('id'),p=byId[id];if(!p){if(document.body.dataset.page==='product'){const h=$('#product-name');if(h)h.textContent='Product not found';const d=$('#product-description');if(d)d.textContent='This product is not available in our current collection. Please return to the shop.';const b=$('#product-add');if(b)b.disabled=true;}return;}document.title=`${p.name} | Lèle Essentials Co.`;$('#product-name').textContent=p.name;$('#product-label').textContent=p.label;$('#product-description').textContent=p.intro;$('#product-size').textContent=p.size;$('#product-price').textContent=money(p);$('#product-main-image').src=asset(p);$('#product-main-image').alt=`Photograph of ${p.name} packaging`;
$('#product-includes').innerHTML=p.includes.map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('');$('#product-highlights').innerHTML=p.highlights.map(x=>`<li>${x}</li>`).join('');$('#product-directions').innerHTML=p.directions.map((x,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><p>${x}</p></li>`).join('');$('#product-notes').textContent=p.notes;$('#product-add').dataset.add=p.id;$('#related-products').innerHTML=PRODUCTS.filter(x=>x.id!==id).map(productCard).join('');const crumbs=$('#breadcrumb-current');if(crumbs)crumbs.textContent=p.name;}
function sendOrder(event){event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const data=new FormData(form),name=String(data.get('name')||'').trim(),phone=String(data.get('phone')||'').replace(/[\s-]/g,''),email=String(data.get('email')||'').trim(),district=String(data.get('district')||'').trim(),division=String(data.get('division')||''),address=String(data.get('address')||'').trim(),notes=String(data.get('notes')||'').trim();
if(!/^(?:\+?880|0)1[3-9]\d{8}$/.test(phone)){alert('Please enter a valid Bangladeshi mobile number (e.g., 017XXXXXXXX).');return;}
const items=cartItems();if(!items.length){alert('Your bag is empty.');return;}
const priced=items.every(p=>Number.isFinite(p.price));const subtotal=priced?`৳${items.reduce((s,p)=>s+p.price*p.qty,0).toLocaleString('en-BD')}`:'To be confirmed by the store';const msg=[`*NEW CASH ON DELIVERY ORDER — ${STORE.name}*`,'',...items.map((p,i)=>`${i+1}. ${p.name} (${p.size}) × ${p.qty} — ${money(p)}`),'',`*Product subtotal:* ${subtotal}`,'*Delivery fee:* To be confirmed','*Payment:* Cash on Delivery','','*CUSTOMER DETAILS*',`Name: ${name}`,`Mobile: ${phone}`,`Email: ${email}`,`Division: ${division}`,`District: ${district}`,`Full address: ${address}`,`Notes: ${notes||'None'}`,'','Please confirm availability, final total and delivery details before dispatch.'];
const url=`https://wa.me/${STORE.whatsapp}?text=${encodeURIComponent(msg.join('\n'))}`;const link=$('#whatsapp-fallback');if(link){link.href=url;link.hidden=false;}const win=window.open(url,'_blank');if(win){try{win.opener=null;}catch(e){}}const status=$('#checkout-status');if(status)status.textContent=win?'WhatsApp opened with your order. Please press Send there to submit it.':'Your WhatsApp order is ready. Select the link below to open WhatsApp and press Send.';
}
function setup(){renderHome();renderProduct();updateCart();document.addEventListener('click',e=>{const t=e.target.closest('button,[data-open-cart],[data-close-cart]');if(!t)return;if(t.matches('[data-add]'))add(t.dataset.add);else if(t.matches('[data-qty]'))updateQty(t.dataset.id,Number(t.dataset.qty));else if(t.matches('[data-remove]')){delete cart[t.dataset.remove];save();}else if(t.matches('[data-open-cart]'))openCart();else if(t.matches('[data-close-cart]'))closeCart();else if(t.matches('#checkout-open'))openCheckout();else if(t.matches('[data-close-checkout]'))closeCheckout();else if(t.matches('[data-menu-toggle]')){const menu=$('#mobile-nav');const show=menu.hidden;menu.hidden=!show;t.setAttribute('aria-expanded',String(show));}});$('#overlay')?.addEventListener('click',closeCart);$('#order-form')?.addEventListener('submit',sendOrder);document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeCart();closeCheckout();}});}
document.addEventListener('DOMContentLoaded',setup);
